<script setup lang="ts">
import Pagination from '../components/Pagination.vue'
import {usePagination} from '../composables/usePagination'
import {computed,onMounted,ref} from 'vue'
import {ArrowUpRight,BookOpen,Search,SlidersHorizontal} from 'lucide-vue-next'
import {api,type InstrumentCatalog} from '../services/api'
import type {SignalRadar} from '../types/radar'
import type {ValidationSnapshot} from '../types/research'
import {useExperience} from '../composables/useExperience'
import {researchPath} from '../utils/marketNavigation'
const {isSimple}=useExperience()
const catalog=ref<InstrumentCatalog|null>(null),scan=ref<SignalRadar|null>(null),validation=ref<ValidationSnapshot|null>(null)
const query=ref(''),error=ref(''),catalogError=ref(''),loading=ref(true),selected=ref('ALL')
const methods=[
  {id:'MOMENTUM_BREAKOUT',name:'跟随已经出现的趋势',technical:'放量通道突破',body:'观察价格是否突破过去一段时间的高低点，再核对趋势与成交量。',failure:'震荡反复、假突破或成交成本上升时可能失效。'},
  {id:'BOLLINGER_REVERSAL',name:'观察偏离与回归',technical:'布林均值回归',body:'观察价格是否明显偏离近期均值，再研究是否存在回归条件。',failure:'持续单边行情中，价格可能继续偏离，不能只凭“便宜”或“贵”判断。'},
  {id:'DUAL_THRUST',name:'观察区间是否被打破',technical:'Dual Thrust',body:'把历史波动区间与当日开盘价结合，观察价格是否跨过设定边界。',failure:'跳空、反复穿越边界和参数选择都会影响结果。'},
]
const products=computed(()=>{
  const needle=query.value.trim().toUpperCase()
  return (catalog.value?.exchanges.flatMap(g=>g.instruments)??[]).filter(i=>!needle||`${i.name} ${i.mainSymbol}`.toUpperCase().includes(needle))
})
const matches=computed(()=>(scan.value?.items??[]).filter(i=>selected.value==='ALL'||i.strategy===selected.value))
const {items:pagedProducts,page:productPage,total:productTotal}=usePagination(products,8,[query])
const {items:pagedMatches,page:matchPage,total:matchTotal}=usePagination(matches,12,[selected])
async function load(){loading.value=true;error.value='';catalogError.value='';await Promise.allSettled([
  api.instruments().then(v=>catalog.value=v).catch(()=>catalogError.value='品种目录暂不可用，可先查看方法说明或进入行情市场'),
  api.radarSignals().then(v=>scan.value=v).catch(e=>error.value=e instanceof Error?e.message:'策略条件暂不可用'),
  api.validation().then(v=>validation.value=v).catch(()=>validation.value=null),
]);loading.value=false}
onMounted(()=>void load())
</script>
<template>
  <div class="page-stack research-hub">
    <section class="research-intro"><span>从理解方法开始</span><h2>先问为什么，再看研究结果。</h2><p>这里汇集研究方法和多个品种。每一种方法都有适用条件与失效情景，满足条件也不等于未来会盈利。</p><div><RouterLink to="/learn"><BookOpen :size="15"/>从零了解术语</RouterLink><RouterLink to="/backtest">在历史数据中验证 ↗</RouterLink><RouterLink to="/paper">用虚拟资金练习 ↗</RouterLink></div></section>
    <section class="choose-research"><header><div><h2>你想了解哪个品种？</h2><p>选定后进入单品种研究。默认实证模式，风险试算由你主动展开。</p></div><label><Search :size="16"/><input v-model="query" type="search" aria-label="搜索研究品种" placeholder="输入品种名称或代码"/></label></header><p v-if="catalogError" class="notice" role="alert">{{catalogError}}</p><div class="product-links"><RouterLink v-for="item in pagedProducts" :key="item.mainSymbol" :to="researchPath(item.mainSymbol)"><strong>{{item.name}}</strong><span>{{item.mainSymbol}} · {{item.exchange}} <ArrowUpRight :size="13"/></span></RouterLink></div><p v-if="!products.length&&!loading&&!catalogError" class="empty">没有匹配的品种，试试其他名称或代码。</p><Pagination v-model:page="productPage" :page-size="8" :total="productTotal" label="研究品种分页" /><RouterLink to="/market" class="all-products">浏览全部品种 ↗</RouterLink></section>
    <section class="method-section"><header><SlidersHorizontal :size="18"/><div><h2>三种观察市场的方法</h2><p>点击卡片可筛选下方的条件记录；这是方法说明与规则扫描，不是收益排名。</p></div></header><div class="method-grid"><button v-for="method in methods" :key="method.id" type="button" :aria-pressed="selected===method.id" @click="selected=selected===method.id?'ALL':method.id"><span>{{method.technical}}</span><h3>{{isSimple?method.name:method.technical}}</h3><p>{{method.body}}</p><div><b>需要留意</b><p>{{method.failure}}</p></div><footer>当前 {{scan?.groups?.find(g=>g.id===method.id)?.matched??'—'}} 条条件记录 · {{selected===method.id?'再次点击看全部':'查看记录'}}</footer></button></div></section>
    <section class="condition-section"><header><div><h2>哪些品种满足了观察条件？</h2><p>已完成日线 · {{scan?.scannedCount??'—'}} / {{scan?.universeCount??'—'}} 品种 · 数据日期 {{scan?.dataTimestamp?.slice(0,10)??'待观测'}}</p></div><button class="quiet" type="button" :disabled="loading" @click="load">{{loading?'核验中':'更新资料'}}</button></header><p v-if="error||scan?.status==='UNAVAILABLE'" class="notice" role="alert">{{error||scan?.message}}</p><p v-else-if="loading&&!scan" role="status" class="empty">正在读取多个品种的日线条件…</p><div class="condition-list"><RouterLink v-for="item in pagedMatches" :key="item.id" :to="researchPath(item.symbol)"><div><strong>{{item.name}}</strong><small>{{item.symbol}} · {{methods.find(m=>m.id===item.strategy)?.technical}}</small></div><span :class="item.signal==='BUY'?'positive':'negative'">{{item.signal==='BUY'?'偏多条件':'偏空条件'}}</span><ArrowUpRight :size="14"/></RouterLink></div><Pagination v-model:page="matchPage" :page-size="12" :total="matchTotal" label="策略条件分页" /><p v-if="scan&&!matches.length&&scan.status!=='UNAVAILABLE'" class="empty">当前没有满足所选规则的品种，不强行生成机会。</p><p class="scope-note">{{scan?.message}}<span v-if="scan?.status==='DEGRADED'"> 当前为上次成功扫描快照。</span></p></section>
    <section class="validation-note"><h2>这些方法经过了什么验证？</h2><p v-if="loading&&!validation" role="status">正在读取验证范围…</p><p v-else-if="validation?.status==='RETROSPECTIVE_CHECKED'">已有 {{validation.assets}} 个品种、{{validation.cases}} 组固定参数的回顾性复核，检查成交、换月和成本假设的一致性。<b>独立样本外表现与盈利能力尚未验证。</b></p><p v-else>当前没有与模型版本一致的完整验证结果可供确认。历史收益不作为未来承诺。</p><RouterLink to="/backtest">查看验证范围、限制与回测工具 ↗</RouterLink></section>
  </div>
</template>
<style scoped>
